(119, '2024/2025', 'Professional Diploma in Health Information Management', '300', 'First', 'BIOSTATISTICS', 'PREPARATORY', 'OBJECTIVE', 'GENERAL', 100, 100, 'text', 18, '<p style=\"font-size: 24px; font-family: Arial;\">The Geometric mean of 3,4,8 =<br />\nA. 9.797. B. 8.98. C. 8.787. D. 9.91</p>', 'A', 'blank.jpg', NULL, NULL),
(120, '2024/2025', 'Professional Diploma in Health Information Management', '300', 'First', 'BIOSTATISTICS', 'PREPARATORY', 'OBJECTIVE', 'GENERAL', 100, 100, 'text', 19, '<p style=\"font-size: 24px; font-family: Arial;\">The mode of 3,5,8,10,10,12,15,16 = A. 16. B. 15. C 10. D. 12</p>', 'C', 'blank.jpg', NULL, NULL),
(121, '2024/2025', 'Professional Diploma in Health Information Management', '300', 'First', 'BIOSTATISTICS', 'PREPARATORY', 'OBJECTIVE', 'GENERAL', 100, 100, 'text', 20, '<p style=\"font-size: 24px; font-family: Arial;\">The median of 3,4,4,5,6,8,8,8,10 = A. 6. B. 5. C. 8.  D. 10</p>', 'A', 'blank.jpg', NULL, NULL),
(122, '2024/2025', 'Professional Diploma in Health Information Management', '300', 'First', 'BIOSTATISTICS', 'PREPARATORY', 'OBJECTIVE', 'GENERAL', 100, 100, 'text', 21, '<p style=\"font-size: 24px; font-family: Arial;\">What does the Crude Birth Rate (CBR) measure?<br />\nA) Number of births per 1000 women aged 15-49 years<br />\nB) Number of births per 1000 population<br />\nC) Number of births per 1000 live births<br />\nD) Number of births per 1000 household</p>', 'B', 'blank.jpg', NULL, NULL);
INSERT INTO `questions` (`id`, `session1`, `department`, `level`, `semester`, `course`, `exam_type`, `exam_mode`, `exam_category`, `no_of_qst`, `upload_no_of_qst`, `question_type`, `question_no`, `question`, `answer`, `graphic`, `created_at`, `updated_at`) VALUES
(123, '2024/2025', 'Professional Diploma in Health Information Management', '300', 'First', 'BIOSTATISTICS', 'PREPARATORY', 'OBJECTIVE', 'GENERAL', 100, 100, 'text', 22, '<p style=\"font-size: 24px; font-family: Arial;\">Standard deviation    x 100%   =<br />\n   Arithmetic mean<br />\n A. Coefficient of variation.  B. Mean deviation   <br />\nC. Standard deviation    D. Variance <br />\n</p>', 'C', 'blank.jpg', NULL, NULL),
(124, '2024/2025', 'Professional Diploma in Health Information Management', '300', 'First', 'BIOSTATISTICS', 'PREPARATORY', 'OBJECTIVE', 'GENERAL', 100, 100, 'text', 23, '<p style=\"font-size: 24px; font-family: Arial;\">One of the following is a probability sampling<br />\nA. Simple random<br />\nB. Convenience<br />\nC. Haphazard<br />\nD. Quota</p>', 'A', 'blank.jpg', NULL, NULL),
(125, '2024/2025', 'Professional Diploma in Health Information Management', '300', 'First', 'BIOSTATISTICS', 'PREPARATORY', 'OBJECTIVE', 'GENERAL', 100, 100, 'text', 24, '<p style=\"font-size: 24px; font-family: Arial;\">One of the following is a non-probability sampling<br />\nA. Stratified<br />\nB. Cluster<br />\nC. Multi stage<br />\nD. Quata</p>', 'D', 'blank.jpg', NULL, NULL),
(126, '2024/2025', 'Professional Diploma in Health Information Management', '300', 'First', 'BIOSTATISTICS', 'PREPARATORY', 'OBJECTIVE', 'GENERAL', 100, 100, 'text', 25, '<p style=\"font-size: 24px; font-family: Arial;\">The arithmetic mean of 84, 91, 72, 68, 87, 78 =<br />\nA. 88. B. 80. C. 82. D. 8.80</p>', 'B', 'blank.jpg', NULL, NULL),
(127, '2024/2025', 'Professional Diploma in Health Information Management', '300', 'First', 'BIOSTATISTICS', 'PREPARATORY', 'OBJECTIVE', 'GENERAL', 100, 100, 'text', 26, '<p style=\"font-size: 24px; font-family: Arial;\">The measure that divides a distribution into 2 equal parts is called<br />\nA. Mode. B. Median. C. Quartile D. Mean</p>', 'B', 'blank.jpg', NULL, NULL),
(128, '2024/2025', 'Professional Diploma in Health Information Management', '300', 'First', 'BIOSTATISTICS', 'PREPARATORY', 'OBJECTIVE', 'GENERAL', 100, 100, 'text', 27, '<p style=\"font-size: 24px; font-family: Arial;\">The formula L1 + (f1 ? f0) (L2  - L1<br />\n(2f1 ? f0  - f2)   =<br />\nA. Median. B. Mode. C. Mean. D. Q2</p>', 'B', 'blank.jpg', NULL, NULL),
(129, '2024/2025', 'Professional Diploma in Health Information Management', '300', 'First', 'BIOSTATISTICS', 'PREPARATORY', 'OBJECTIVE', 'GENERAL', 100, 100, 'text', 28, '<p style=\"font-size: 24px; font-family: Arial;\">The formula ?IX?-??I??defines<br />\nN<br />\nA. Mean deviation. B. Standard deviation. Variance D. Semi-quatile</p>', 'C', 'blank.jpg', NULL, NULL),
(130, '2024/2025', 'Professional Diploma in Health Information Management', '300', 'First', 'BIOSTATISTICS', 'PREPARATORY', 'OBJECTIVE', 'GENERAL', 100, 100, 'text', 29, '<p style=\"font-size: 24px; font-family: Arial;\">Statistics is useful in the following areas but<br />\nA. Monitoring and Evaluation<br />\nB. Decision making<br />\nC. Population census<br />\nD. Contractive measure</p>', 'D', 'blank.jpg', NULL, NULL),
(131, '2024/2025', 'Professional Diploma in Health Information Management', '300', 'First', 'BIOSTATISTICS', 'PREPARATORY', 'OBJECTIVE', 'GENERAL', 100, 100, 'text', 30, '<p style=\"font-size: 24px; font-family: Arial;\">The type of data collected by an investigator who is going to use it for Specific reason is called<br />\nA. Primary data. B. Secondary data.<br />\nC. Tertiary data. D. Government data</p>', 'A', 'blank.jpg', NULL, NULL),
(132, '2024/2025', 'Professional Diploma in Health Information Management', '300', 'First', 'BIOSTATISTICS', 'PREPARATORY', 'OBJECTIVE', 'GENERAL', 100, 100, 'text', 31, '<p style=\"font-size: 24px; font-family: Arial;\">The tabular arrangement of class intervals with associated frequencies  called<br />\nA . Frequency polygon. B. Frequency distribution.<br />\nC. Frequency curve D. Frequency ogive</p>', 'B', 'blank.jpg', NULL, NULL),
(133, '2024/2025', 'Professional Diploma in Health Information Management', '300', 'First', 'BIOSTATISTICS', 'PREPARATORY', 'OBJECTIVE', 'GENERAL', 100, 100, 'text', 32, '<p style=\"font-size: 24px; font-family: Arial;\">The type of data used by other person other than the person who   collects the data for other statistical enquiry is called<br />\nA. Secondary data. B. Primary data C. tertiary data D. frequency data</p>', 'A', 'blank.jpg', NULL, NULL),
(134, '2024/2025', 'Professional Diploma in Health Information Management', '300', 'First', 'BIOSTATISTICS', 'PREPARATORY', 'OBJECTIVE', 'GENERAL', 100, 100, 'text', 33, '<p style=\"font-size: 24px; font-family: Arial;\">A small scale replica of the actual survey and is carried out before the actual survey is undertaken is called<br />\nA. Pilot survey B. Simple survey C. Pre-test survey D. Post survey</p>', 'A', 'blank.jpg', NULL, NULL),
(135, '2024/2025', 'Professional Diploma in Health Information Management', '300', 'First', 'BIOSTATISTICS', 'PREPARATORY', 'OBJECTIVE', 'GENERAL', 100, 100, 'text', 34, '<p style=\"font-size: 24px; font-family: Arial;\">A statistical enquiry based on a sample and from which inference is made about the population is called<br />\nA. Population survey. B. Population census.<br />\nC. Sample survey        D. Sample statistics</p>', 'C', 'blank.jpg', NULL, NULL),
(136, '2024/2025', 'Professional Diploma in Health Information Management', '300', 'First', 'BIOSTATISTICS', 'PREPARATORY', 'OBJECTIVE', 'GENERAL', 100, 100, 'text', 35, '<p style=\"font-size: 24px; font-family: Arial;\">The list of the population units from which the sample units are identified is called<br />\nA. Frame B. List C. Trend D. Parameter</p>', 'A', 'blank.jpg', NULL, NULL),
(137, '2024/2025', 'Professional Diploma in Health Information Management', '300', 'First', 'BIOSTATISTICS', 'PREPARATORY', 'OBJECTIVE', 'GENERAL', 100, 100, 'text', 36, '<p style=\"font-size: 24px; font-family: Arial;\">Variables whose values occurs in whole numbers are called<br />\nA. Discrete B. Continuous C. Inference.  D. Deductive</p>', 'A', 'blank.jpg', NULL, NULL),
(138, '2024/2025', 'Professional Diploma in Health Information Management', '300', 'First', 'BIOSTATISTICS', 'PREPARATORY', 'OBJECTIVE', 'GENERAL', 100, 100, 'text', 37, '<p style=\"font-size: 24px; font-family: Arial;\">A circular diagram is also known as<br />\nA. Bar chart B. Pie chart C. Line chart Histogram</p>', 'B', 'blank.jpg', NULL, NULL),
(139, '2024/2025', 'Professional Diploma in Health Information Management', '300', 'First', 'BIOSTATISTICS', 'PREPARATORY', 'OBJECTIVE', 'GENERAL', 100, 100, 'text', 38, '<p style=\"font-size: 24px; font-family: Arial;\">A Ogive is also known as<br />\nA. frequency curve B. Cumulative frequency curve<br />\nC. Histogram D. Polygon</p>', 'B', 'blank.jpg', NULL, NULL),
(140, '2024/2025', 'Professional Diploma in Health Information Management', '300', 'First', 'BIOSTATISTICS', 'PREPARATORY', 'OBJECTIVE', 'GENERAL', 100, 100, 'text', 39, '<p style=\"font-size: 24px; font-family: Arial;\">A chart that is formed by rectangles of equal width whose heights are proportional to given values is called<br />\nA. Bar diagram B. Circular diagram C. Pictogram D. Multiple bar chart</p>', 'A', 'blank.jpg', NULL, NULL),
(141, '2024/2025', 'Professional Diploma in Health Information Management', '300', 'First', 'BIOSTATISTICS', 'PREPARATORY', 'OBJECTIVE', 'GENERAL', 100, 100, 'text', 40, '<p style=\"font-size: 24px; font-family: Arial;\">The reciprocal of the arithmetic mean of the reciprocals of numbers is called<br />\nA. Geometric mean B. Harmonic mean C. Arithmetic mean D. Deviational mean</p>', 'B', 'blank.jpg', NULL, NULL),
(142, '2024/2025', 'Professional Diploma in Health Information Management', '300', 'First', 'BIOSTATISTICS', 'PREPARATORY', 'OBJECTIVE', 'GENERAL', 100, 100, 'text', 41, '<p style=\"font-size: 24px; font-family: Arial;\">Variables that uses attributes as values are called<br />\nA. Qualitative  B. Quantitative C. Attributive. D. Nominal</p>', 'A', 'blank.jpg', NULL, NULL),
(143, '2024/2025', 'Professional Diploma in Health Information Management', '300', 'First', 'BIOSTATISTICS', 'PREPARATORY', 'OBJECTIVE', 'GENERAL', 100, 100, 'text', 42, '<p style=\"font-size: 24px; font-family: Arial;\">The difference between the largest and the lowest figure in a set of observation is called<br />\nA. Median B. Range C. Q range D. Modal range</p>', 'B', 'blank.jpg', NULL, NULL),
(144, '2024/2025', 'Professional Diploma in Health Information Management', '300', 'First', 'BIOSTATISTICS', 'PREPARATORY', 'OBJECTIVE', 'GENERAL', 100, 100, 'text', 43, '<p style=\"font-size: 24px; font-family: Arial;\">The formula for semi-interquartile range is A. Q = ?(Q3 - Q1). B. (Q3  ?  Q2)<br />\nC. (Q3 - Q1)2    D. 1/3(Q3 ? Q2)</p>', 'A', 'blank.jpg', NULL, NULL),
(145, '2024/2025', 'Professional Diploma in Health Information Management', '300', 'First', 'BIOSTATISTICS', 'PREPARATORY', 'OBJECTIVE', 'GENERAL', 100, 100, 'text', 44, '<p style=\"font-size: 24px; font-family: Arial;\">A fair coin is tossed twice, what is the probability that at least one head appears<br />\nA. HH,HT,TH,TT. B. TT,HH, TH<br />\nC. HT,TH,HH  D. HT,TT, HT</p>', 'C', 'blank.jpg', NULL, NULL),
(146, '2024/2025', 'Professional Diploma in Health Information Management', '300', 'First', 'BIOSTATISTICS', 'PREPARATORY', 'OBJECTIVE', 'GENERAL', 100, 100, 'text', 45, '<p style=\"font-size: 24px; font-family: Arial;\">A. set whose elements represents all possible outcomes of an experiment is called<br />\nA. Sample point B. Sample space<br />\nC. Stocastic D. Event</p>', 'B', 'blank.jpg', NULL, NULL),
(147, '2024/2025', 'Professional Diploma in Health Information Management', '300', 'First', 'BIOSTATISTICS', 'PREPARATORY', 'OBJECTIVE', 'GENERAL', 100, 100, 'text', 46, '<p style=\"font-size: 24px; font-family: Arial;\">An element of sample space is called<br />\nA. Sample point B. Sure event<br />\nC. Impossible event D. Independent event</p>', 'A', 'blank.jpg', NULL, NULL),
(148, '2024/2025', 'Professional Diploma in Health Information Management', '300', 'First', 'BIOSTATISTICS', 'PREPARATORY', 'OBJECTIVE', 'GENERAL', 100, 100, 'text', 47, '<p style=\"font-size: 24px; font-family: Arial;\">An event whose probability is one (1) is known as<br />\nA. Absolute event B. Sure event<br />\nC. Less than one event D. Impossible event</p>', 'B', 'blank.jpg', NULL, NULL),
(149, '2024/2025', 'Professional Diploma in Health Information Management', '300', 'First', 'BIOSTATISTICS', 'PREPARATORY', 'OBJECTIVE', 'GENERAL', 100, 100, 'text', 48, '<p style=\"font-size: 24px; font-family: Arial;\">An event whose probability is zero is called<br />\nA. Impossible event  B. Sure event C < 1 event D > 1 event</p>', 'A', 'blank.jpg', NULL, NULL),
(150, '2024/2025', 'Professional Diploma in Health Information Management', '300', 'First', 'BIOSTATISTICS', 'PREPARATORY', 'OBJECTIVE', 'GENERAL', 100, 100, 'text', 49, '<p style=\"font-size: 24px; font-family: Arial;\">The principle of insufficient reason is known as<br />\nA. Classical approach.<br />\nB. Relative frequency approach<br />\nC. Axiomatic approach D. Subjective approach</p>', 'A', 'blank.jpg', NULL, NULL),
(151, '2024/2025', 'Professional Diploma in Health Information Management', '300', 'First', 'BIOSTATISTICS', 'PREPARATORY', 'OBJECTIVE', 'GENERAL', 100, 100, 'text', 50, '<p style=\"font-size: 24px; font-family: Arial;\">The probability assigned to an event based on experience, information and believe is known as<br />\nA. Objective approach. B. Subjective approach<br />\nC. Relative approach D. Frequency approach</p>', 'B', 'blank.jpg', NULL, NULL),
(152, '2024/2025', 'Professional Diploma in Health Information Management', '300', 'First', 'BIOSTATISTICS', 'PREPARATORY', 'OBJECTIVE', 'GENERAL', 100, 100, 'text', 51, '<p style=\"font-size: 24px; font-family: Arial;\">What is medical demography?<br />\nA) The study of individual patient histories<br />\nB) The study of the distribution  and determinants  of health- related states and events in populations<br />\nC) The analysis of healthcare costs<br />\nD) The study of genetic factors in disease</p>', 'B', 'blank.jpg', NULL, NULL),
(153, '2024/2025', 'Professional Diploma in Health Information Management', '300', 'First', 'BIOSTATISTICS', 'PREPARATORY', 'OBJECTIVE', 'GENERAL', 100, 100, 'text', 52, '<p style=\"font-size: 24px; font-family: Arial;\">What is life expectancy?<br />\nA) The number of deaths per 1,000 live births<br />\nB) The average number of years a person is expected to live based on current mortality rates<br />\nC) The number of people per square kilometer<br />\nD) The average age at first birth</p>', 'B', 'blank.jpg', NULL, NULL),
(154, '2024/2025', 'Professional Diploma in Health Information Management', '300', 'First', 'BIOSTATISTICS', 'PREPARATORY', 'OBJECTIVE', 'GENERAL', 100, 100, 'text', 53, '<p style=\"font-size: 24px; font-family: Arial;\">What is infant mortality rate?<br />\nA) The number of deaths of children under five years old per 1,000 live births<br />\nB) The number of deaths of infants under one year old per 1,000 live births<br />\nC) The number of stillbirths per 1,000 live births<br />\nD) The number of premature births per 1,000 live births</p>', 'B', 'blank.jpg', NULL, NULL),
(155, '2024/2025', 'Professional Diploma in Health Information Management', '300', 'First', 'BIOSTATISTICS', 'PREPARATORY', 'OBJECTIVE', 'GENERAL', 100, 100, 'text', 54, '<p style=\"font-size: 24px; font-family: Arial;\">What is the crude birth rate?A) The number of live births per 1,000 people in a given year<br />\nB) The number of pregnancies per 1,000 women in a given year<br />\nC) The number of deaths per 1,000 people in a given year<br />\nD) The number of births per 1,000 married women in a given year</p>', 'A', 'blank.jpg', NULL, NULL),
(156, '2024/2025', 'Professional Diploma in Health Information Management', '300', 'First', 'BIOSTATISTICS', 'PREPARATORY', 'OBJECTIVE', 'GENERAL', 100, 100, 'text', 55, '<p style=\"font-size: 24px; font-family: Arial;\">What is the total fertility rate (TFR)?<br />\nA) The number of births per 1,000 women aged 15-49<br />\nB) The average number of children a woman would have in her lifetime based on current birth rates<br />\nC) The number of pregnancies per 1,000 women aged 15-49<br />\nD) The number of live births per 1,000 people</p>', 'B', 'blank.jpg', NULL, NULL),
(157, '2024/2025', 'Professional Diploma in Health Information Management', '300', 'First', 'BIOSTATISTICS', 'PREPARATORY', 'OBJECTIVE', 'GENERAL', 100, 100, 'text', 56, '<p style=\"font-size: 24px; font-family: Arial;\">What is the dependency ratio?<br />\nA) The ratio of children to adults in a population<br />\nB) The ratio of dependents (people aged 0-14 and 65+) to the working-age population (15-64)<br />\nC) The ratio of the elderly population to the total population<br />\nD) The ratio of healthcare providers to patients</p>', 'B', 'blank.jpg', NULL, NULL),
(158, '2024/2025', 'Professional Diploma in Health Information Management', '300', 'First', 'BIOSTATISTICS', 'PREPARATORY', 'OBJECTIVE', 'GENERAL', 100, 100, 'text', 57, '<p style=\"font-size: 24px; font-family: Arial;\">What is population density?<br />\nA) The number of births per 1,000 people<br />\nB) The number of people per unit area<br />\nC) The growth rate of a population<br />\nD) The proportion of urban to rural population</p>', 'B', 'blank.jpg', NULL, NULL),
(159, '2024/2025', 'Professional Diploma in Health Information Management', '300', 'First', 'BIOSTATISTICS', 'PREPARATORY', 'OBJECTIVE', 'GENERAL', 100, 100, 'text', 58, '<p style=\"font-size: 24px; font-family: Arial;\">What is the maternal mortality ratio (MMR)?<br />\nA) The number of maternal deaths per 100,000 live births<br />\nB) The number of infant deaths per 1,000 live birthsC) The number of stillbirths per 1,000 live births<br />\nD)The   number   of   maternal   deaths   per   1,000   women   of reproductive age</p>', 'A', 'blank.jpg', NULL, NULL),
(160, '2024/2025', 'Professional Diploma in Health Information Management', '300', 'First', 'BIOSTATISTICS', 'PREPARATORY', 'OBJECTIVE', 'GENERAL', 100, 100, 'text', 59, '<p style=\"font-size: 24px; font-family: Arial;\">What is prevalence?<br />\nA) The number of new cases of a disease in a population at risk<br />\nB) The total number of cases of a disease in a population at a specific time<br />\nC)  The  number  of  deaths  due  to  a  specific  disease  in  a population<br />\nD) The rate of recovery from a disease in a population</p>', 'B', 'blank.jpg', NULL, NULL),
(161, '2024/2025', 'Professional Diploma in Health Information Management', '300', 'First', 'BIOSTATISTICS', 'PREPARATORY', 'OBJECTIVE', 'GENERAL', 100, 100, 'text', 60, '<p style=\"font-size: 24px; font-family: Arial;\">What is incidence?<br />\nA) The total number of cases of a disease in a population<br />\nB)  The  number  of  deaths  due  to  a  specific  disease  in  a population<br />\nC)  The  number  of  new  cases  of  a  disease  that  occur  in  a specified period of time in a population at risk<br />\nD) The rate of recovery from a disease in a population</p>', 'C', 'blank.jpg', NULL, NULL),
(162, '2024/2025', 'Professional Diploma in Health Information Management', '300', 'First', 'BIOSTATISTICS', 'PREPARATORY', 'OBJECTIVE', 'GENERAL', 100, 100, 'text', 61, '<p style=\"font-size: 24px; font-family: Arial;\">What is the demographic transition model?<br />\nA) A model describing changes in population structure due to urbanization<br />\nB) A model that describes population change over time, typically in four stages: pre-industrial, transitional, industrial, and post-industrial<br />\nC) A model explaining migration patterns in relation to economic development<br />\nD) A model forecasting future population growth</p>', 'B', 'blank.jpg', NULL, NULL),
(163, '2024/2025', 'Professional Diploma in Health Information Management', '300', 'First', 'BIOSTATISTICS', 'PREPARATORY', 'OBJECTIVE', 'GENERAL', 100, 100, 'text', 62, '<p style=\"font-size: 24px; font-family: Arial;\">What is a cohort study?<br />\nA) A study that compares individuals with a specific condition to those without the condition<br />\nB) A study that collects data from a population at a single point in time<br />\nC)  A  study that  follows  a  group  of  people  with  a  common characteristic over time<br />\nD)  An  experimental  study  where  participants  are  randomly assigned to groups</p>', 'C', 'blank.jpg', NULL, NULL),
(164, '2024/2025', 'Professional Diploma in Health Information Management', '300', 'First', 'BIOSTATISTICS', 'PREPARATORY', 'OBJECTIVE', 'GENERAL', 100, 100, 'text', 63, '<p style=\"font-size: 24px; font-family: Arial;\">What is life table?<br />\nA) A table summarizing population age structure<br />\nB) A table showing the probability of dying at each age or age interval<br />\nC) A table listing birth rates in different regions<br />\nD) A table displaying health expenditures per capita</p>', 'B', 'blank.jpg', NULL, NULL),
(165, '2024/2025', 'Professional Diploma in Health Information Management', '300', 'First', 'BIOSTATISTICS', 'PREPARATORY', 'OBJECTIVE', 'GENERAL', 100, 100, 'text', 64, '<p style=\"font-size: 24px; font-family: Arial;\">What does TOI stand for in hospital statistics?<br />\nA) Time of Incident<br />\nB) Turnover Interval<br />\nC) Total Operational Input<br />\nD) Total Outpatient Index</p>', 'B', 'blank.jpg', NULL, NULL),
(166, '2024/2025', 'Professional Diploma in Health Information Management', '300', 'First', 'BIOSTATISTICS', 'PREPARATORY', 'OBJECTIVE', 'GENERAL', 100, 100, 'text', 65, '<p style=\"font-size: 24px; font-family: Arial;\">How is Bed Occupancy Rate (BOR) calculated?<br />\nA) (Total Discharges / Total Beds) x 100<br />\nB) (Total Inpatient Days / Total Bed Days) x 100 C) (Total Admissions / Total Beds) x 100<br />\nD) (Total Outpatient Visits / Total Bed Days) x 100</p>', 'B', 'blank.jpg', NULL, NULL),
(167, '2024/2025', 'Professional Diploma in Health Information Management', '300', 'First', 'BIOSTATISTICS', 'PREPARATORY', 'OBJECTIVE', 'GENERAL', 100, 100, 'text', 66, '<p style=\"font-size: 24px; font-family: Arial;\">Which term refers to the average number of days a patient stays in the hospital?<br />\nA) Turnover Interval<br />\nB) Bed Occupancy Rate<br />\nC) Average Length of Stay<br />\nD) Bed Turnover Rate</p>', 'C', 'blank.jpg', NULL, NULL),
(168, '2024/2025', 'Professional Diploma in Health Information Management', '300', 'First', 'BIOSTATISTICS', 'PREPARATORY', 'OBJECTIVE', 'GENERAL', 100, 100, 'text', 67, '<p style=\"font-size: 24px; font-family: Arial;\">What does D+D stand for in hospital statistics?<br />\nA) Discharges and Deaths<br />\nB) Doctors and Diagnostics<br />\nC) Days and Departments<br />\nD) Data and Decisions</p>', 'A', 'blank.jpg', NULL, NULL),
(169, '2024/2025', 'Professional Diploma in Health Information Management', '300', 'First', 'BIOSTATISTICS', 'PREPARATORY', 'OBJECTIVE', 'GENERAL', 100, 100, 'text', 68, '<p style=\"font-size: 24px; font-family: Arial;\">How is the Average Daily Census (ADC) calculated?<br />\nA) (Total Admissions / Total Days)<br />\nB) (Total Inpatient Days / Total Days)<br />\nC) (Total Discharges / Total Days)<br />\nD) (Total Bed Days / Total Admissions)</p>', 'B', 'blank.jpg', NULL, NULL),
(170, '2024/2025', 'Professional Diploma in Health Information Management', '300', 'First', 'BIOSTATISTICS', 'PREPARATORY', 'OBJECTIVE', 'GENERAL', 100, 100, 'text', 69, '<p style=\"font-size: 24px; font-family: Arial;\">What does ABD stand for in hospital statistics?<br />\nA) Available Bed Days<br />\nB) Average Bed Days<br />\nC) Actual Bed Days<br />\nD) Annual Bed Days</p>', 'B', 'blank.jpg', NULL, NULL),
(171, '2024/2025', 'Professional Diploma in Health Information Management', '300', 'First', 'BIOSTATISTICS', 'PREPARATORY', 'OBJECTIVE', 'GENERAL', 100, 100, 'text', 70, '<p style=\"font-size: 24px; font-family: Arial;\">What does OBD stand for in hospital statistics?<br />\nA) Outpatient Bed Days<br />\nB) Overall Bed Days<br />\nC) Occupied Bed Days<br />\nD) Operational Bed Days</p>', 'C', 'blank.jpg', NULL, NULL),
(172, '2024/2025', 'Professional Diploma in Health Information Management', '300', 'First', 'BIOSTATISTICS', 'PREPARATORY', 'OBJECTIVE', 'GENERAL', 100, 100, 'text', 71, '<p style=\"font-size: 24px; font-family: Arial;\">Which metric is used to measure the efficiency of bed usage in a hospital?<br />\nA) Bed Turnover Rate<br />\nB) Average Length of Stay<br />\nC) Bed Occupancy Rate<br />\nD) Admission Rate</p>', 'C', 'blank.jpg', NULL, NULL),
(173, '2024/2025', 'Professional Diploma in Health Information Management', '300', 'First', 'BIOSTATISTICS', 'PREPARATORY', 'OBJECTIVE', 'GENERAL', 100, 100, 'text', 72, '<p style=\"font-size: 24px; font-family: Arial;\">Which of the following is included in the calculation of inpatient days?<br />\nA) Each day a patient spends in the hospital<br />\nB) Days a patient spends in outpatient care<br />\nC) Days patients spend in the emergency department only<br />\nD) Days spent in administrative processes</p>', 'A', 'blank.jpg', NULL, NULL),
(174, '2024/2025', 'Professional Diploma in Health Information Management', '300', 'First', 'BIOSTATISTICS', 'PREPARATORY', 'OBJECTIVE', 'GENERAL', 100, 100, 'text', 73, '<p style=\"font-size: 24px; font-family: Arial;\">How is the Bed Turnover Rate (BTR) calculated?<br />\nA) (Total Bed Days / Total Admissions)<br />\nB) (Total Discharges and Deaths / Total Beds)<br />\nC) (Total Inpatient Days / Total Discharges)<br />\nD) (Total Beds / Total Inpatient Days)</p>', 'B', 'blank.jpg', NULL, NULL),
(175, '2024/2025', 'Professional Diploma in Health Information Management', '300', 'First', 'BIOSTATISTICS', 'PREPARATORY', 'OBJECTIVE', 'GENERAL', 100, 100, 'text', 74, '<p style=\"font-size: 24px; font-family: Arial;\">What does the term \'Bed Statement\' refer to in hospital statistics?<br />\nA) The financial statement of the hospital<br />\nB) A report detailing bed availability and occupancy C) A summary of patient discharges and admissions<br />\nD) A record of hospital staff assignments</p>', 'B', 'blank.jpg', NULL, NULL),
(176, '2024/2025', 'Professional Diploma in Health Information Management', '300', 'First', 'BIOSTATISTICS', 'PREPARATORY', 'OBJECTIVE', 'GENERAL', 100, 100, 'text', 75, '<p style=\"font-size: 24px; font-family: Arial;\">What is the significance of the Turnover Interval (TOI)?<br />\nA) It measures the average length of stay<br />\nB) It calculates the bed occupancy rate<br />\nC) It indicates the time taken to prepare a bed for the next patient<br />\nD) It shows the number of discharges per bed</p>', 'C', 'blank.jpg', NULL, NULL),
(177, '2024/2025', 'Professional Diploma in Health Information Management', '300', 'First', 'BIOSTATISTICS', 'PREPARATORY', 'OBJECTIVE', 'GENERAL', 100, 100, 'text', 76, '<p style=\"font-size: 24px; font-family: Arial;\">How is the total number of bed days calculated?<br />\nA) Number of beds x Number of days in the period<br />\nB) Total admissions x Average length of stay<br />\nC) Total discharges x Average daily census<br />\nD) Number of occupied beds x Number of days in the period</p>', 'A', 'blank.jpg', NULL, NULL),
(178, '2024/2025', 'Professional Diploma in Health Information Management', '300', 'First', 'BIOSTATISTICS', 'PREPARATORY', 'OBJECTIVE', 'GENERAL', 100, 100, 'text', 77, '<p style=\"font-size: 24px; font-family: Arial;\">Which metric is used to determine how often hospital beds turn over in a given period?<br />\nA) Average Length of Stay<br />\nB) Bed Turnover Rate<br />\nC) Bed Occupancy Rate<br />\nD) Admission Rate</p>', 'B', 'blank.jpg', NULL, NULL),
(179, '2024/2025', 'Professional Diploma in Health Information Management', '300', 'First', 'BIOSTATISTICS', 'PREPARATORY', 'OBJECTIVE', 'GENERAL', 100, 100, 'text', 78, '<p style=\"font-size: 24px; font-family: Arial;\">What does the Bed Occupancy Rate (BOR) indicate?<br />\nA) The average number of days a bed is occupied<br />\nB) The number of beds occupied at the end of the day<br />\nC) The percentage of available beds that are occupied over aspecific period<br />\nD) The number of admissions per bed</p>', 'C', 'blank.jpg', NULL, NULL),
(180, '2024/2025', 'Professional Diploma in Health Information Management', '300', 'First', 'BIOSTATISTICS', 'PREPARATORY', 'OBJECTIVE', 'GENERAL', 100, 100, 'text', 79, '<p style=\"font-size: 24px; font-family: Arial;\">What  is  the  formula  to  calculate  the  average  length  of  stay (ALOS)?<br />\nA) (Total Inpatient Days / Total Beds)<br />\nB) (Total Inpatient Days / Total Discharges)<br />\nC) (Total Admissions / Total Inpatient Days)<br />\nD) (Total Bed Days / Total Occupied Beds)</p>', 'B', 'blank.jpg', NULL, NULL),
(181, '2024/2025', 'Professional Diploma in Health Information Management', '300', 'First', 'BIOSTATISTICS', 'PREPARATORY', 'OBJECTIVE', 'GENERAL', 100, 100, 'text', 80, '<p style=\"font-size: 24px; font-family: Arial;\">Which term refers to the total number of days patients occupy hospital beds over a specific period?<br />\nA) Bed Turnover Rate<br />\nB) Average Daily Census<br />\nC) Occupied Bed Days<br />\nD) Bed Occupancy Rate</p>', 'C', 'blank.jpg', NULL, NULL),
(182, '2024/2025', 'Professional Diploma in Health Information Management', '300', 'First', 'BIOSTATISTICS', 'PREPARATORY', 'OBJECTIVE', 'GENERAL', 100, 100, 'text', 81, '<p style=\"font-size: 24px; font-family: Arial;\">In  hospital  statistics,  what  does  the  Average  Daily  Census (ADC) help to determine?<br />\nA) Number of outpatient visits per day<br />\nB) Average number of inpatients present per day<br />\nC) Total number of admissions per day<br />\nD) Total number of discharges per day</p>', 'B', 'blank.jpg', NULL, NULL),
(183, '2024/2025', 'Professional Diploma in Health Information Management', '300', 'First', 'BIOSTATISTICS', 'PREPARATORY', 'OBJECTIVE', 'GENERAL', 100, 100, 'text', 82, '<p style=\"font-size: 24px; font-family: Arial;\">How is the Bed Occupancy Rate (BOR) expressed?<br />\nA) As a percentage B) As a decimal<br />\nC) As a ratio<br />\nD) As an absolute number</p>', 'A', 'blank.jpg', NULL, NULL),
(184, '2024/2025', 'Professional Diploma in Health Information Management', '300', 'First', 'BIOSTATISTICS', 'PREPARATORY', 'OBJECTIVE', 'GENERAL', 100, 100, 'text', 83, '<p style=\"font-size: 24px; font-family: Arial;\">What  is  the  purpose  of  calculating  the  Average  Bed  Days (ABD)?<br />\nA) To determine the average number of beds in the hospital<br />\nB) To calculate the total number of admissions<br />\nC) To measure the average number of days beds are occupied<br />\nD) To find the total number of bed days</p>', 'C', 'blank.jpg', NULL, NULL),
(185, '2024/2025', 'Professional Diploma in Health Information Management', '300', 'First', 'BIOSTATISTICS', 'PREPARATORY', 'OBJECTIVE', 'GENERAL', 100, 100, 'text', 84, '<p style=\"font-size: 24px; font-family: Arial;\">Which of the following impacts the Turnover Interval (TOI)?<br />\nA) Number of admissions<br />\nB) Efficiency of hospital staff in preparing beds<br />\nC) Average length of stay<br />\nD) Number of outpatient visits</p>', 'B', 'blank.jpg', NULL, NULL),
(186, '2024/2025', 'Professional Diploma in Health Information Management', '300', 'First', 'BIOSTATISTICS', 'PREPARATORY', 'OBJECTIVE', 'GENERAL', 100, 100, 'text', 85, '<p style=\"font-size: 24px; font-family: Arial;\">How is the total number of inpatient days obtained?<br />\nA) Number of admissions x Average length of stay<br />\nB) Sum of days each patient spends in the hospital<br />\nC) Number of occupied beds x Number of days<br />\nD) Number of discharges x Average length of stay</p>', 'B', 'blank.jpg', NULL, NULL),
(187, '2024/2025', 'Professional Diploma in Health Information Management', '300', 'First', 'BIOSTATISTICS', 'PREPARATORY', 'OBJECTIVE', 'GENERAL', 100, 100, 'text', 86, '<p style=\"font-size: 24px; font-family: Arial;\">Why is the Bed Turnover Rate (BTR) important?<br />\nA) It helps measure how frequently beds are utilizedB) It indicates the number of beds available<br />\nC) It shows the average length of stay<br />\nD) It measures patient satisfaction</p>', 'A', 'blank.jpg', NULL, NULL),
(188, '2024/2025', 'Professional Diploma in Health Information Management', '300', 'First', 'BIOSTATISTICS', 'PREPARATORY', 'OBJECTIVE', 'GENERAL', 100, 100, 'text', 87, '<p style=\"font-size: 24px; font-family: Arial;\">What does a high Bed Occupancy Rate (BOR) suggest about a hospital?<br />\nA) Low patient volume<br />\nB) High utilization of beds<br />\nC) High turnover interval<br />\nD) Low efficiency in patient discharge</p>', 'B', 'blank.jpg', NULL, NULL),
(189, '2024/2025', 'Professional Diploma in Health Information Management', '300', 'First', 'BIOSTATISTICS', 'PREPARATORY', 'OBJECTIVE', 'GENERAL', 100, 100, 'text', 88, '<p style=\"font-size: 24px; font-family: Arial;\">What  is  the  primary  use  of  the  Bed  Statement  in  hospital management?<br />\nA) Tracking financial performance<br />\nB) Monitoring bed availability and utilization<br />\nC) Managing staff schedules<br />\nD) Recording patient outcomes</p>', 'B', 'blank.jpg', NULL, NULL),
(190, '2024/2025', 'Professional Diploma in Health Information Management', '300', 'First', 'BIOSTATISTICS', 'PREPARATORY', 'OBJECTIVE', 'GENERAL', 100, 100, 'text', 89, '<p style=\"font-size: 24px; font-family: Arial;\">How does the Average Length of Stay (ALOS) affect hospital planning?<br />\nA) It impacts bed allocation and resource management<br />\nB) It determines the number of admissions<br />\nC) It influences outpatient services<br />\nD) It affects the number of hospital staff</p>', 'A', 'blank.jpg', NULL, NULL),
(191, '2024/2025', 'Professional Diploma in Health Information Management', '300', 'First', 'BIOSTATISTICS', 'PREPARATORY', 'OBJECTIVE', 'GENERAL', 100, 100, 'text', 90, '<p style=\"font-size: 24px; font-family: Arial;\">Which factor is NOT considered in the calculation of the Bed Occupancy Rate (BOR)? A) Total inpatient days<br />\nB) Total outpatient visits<br />\nC) Total bed days<br />\nD) Number of beds available</p>', 'B', 'blank.jpg', NULL, NULL),
(192, '2024/2025', 'Professional Diploma in Health Information Management', '300', 'First', 'BIOSTATISTICS', 'PREPARATORY', 'OBJECTIVE', 'GENERAL', 100, 100, 'text', 91, '<p style=\"font-size: 24px; font-family: Arial;\">What does a low Bed Turnover Rate (BTR) indicate?<br />\nA) Longer average length of stay<br />\nB) Higher bed occupancy rate<br />\nC) More admissions per bed<br />\nD) Higher turnover interval</p>', 'A', 'blank.jpg', NULL, NULL),
(193, '2024/2025', 'Professional Diploma in Health Information Management', '300', 'First', 'BIOSTATISTICS', 'PREPARATORY', 'OBJECTIVE', 'GENERAL', 100, 100, 'text', 92, '<p style=\"font-size: 24px; font-family: Arial;\">Which data is essential for calculating the Average Daily Census (ADC)?<br />\nA) Total number of beds and admissions<br />\nB) Total inpatient days and total days in the period<br />\nC) Total discharges and total inpatient days<br />\nD) Total admissions and average length of stay</p>', 'B', 'blank.jpg', NULL, NULL),
(194, '2024/2025', 'Professional Diploma in Health Information Management', '300', 'First', 'BIOSTATISTICS', 'PREPARATORY', 'OBJECTIVE', 'GENERAL', 100, 100, 'text', 93, '<p style=\"font-size: 24px; font-family: Arial;\">What does a high Average Length of Stay (ALOS) typically indicate about patient care?<br />\nA) High patient turnover<br />\nB) Longer recovery times<br />\nC) Efficient bed usage<br />\nD) Increased number of admissions</p>', 'B', 'blank.jpg', NULL, NULL),
(195, '2024/2025', 'Professional Diploma in Health Information Management', '300', 'First', 'BIOSTATISTICS', 'PREPARATORY', 'OBJECTIVE', 'GENERAL', 100, 100, 'text', 94, '<p style=\"font-size: 24px; font-family: Arial;\">What does the Infant Mortality Rate (IMR) measure? A) Deaths of infants under 1 year per 1000 live births<br />\nB) Deaths of infants aged 1-5 per 1000 live births<br />\nC) Deaths of children under 5 years per 1000 live births<br />\nD) Deaths of newborns in the first month per 1000 live births</p>', 'A', 'blank.jpg', NULL, NULL),
(196, '2024/2025', 'Professional Diploma in Health Information Management', '300', 'First', 'BIOSTATISTICS', 'PREPARATORY', 'OBJECTIVE', 'GENERAL', 100, 100, 'text', 95, '<p style=\"font-size: 24px; font-family: Arial;\">The General Fertility Rate (GFR) is the number of live births per 1000 women aged 15-49 years in a year.<br />\nA.   True<br />\nB.   False</p>', 'A', 'blank.jpg', NULL, NULL),
(197, '2024/2025', 'Professional Diploma in Health Information Management', '300', 'First', 'BIOSTATISTICS', 'PREPARATORY', 'OBJECTIVE', 'GENERAL', 100, 100, 'text', 96, '<p style=\"font-size: 24px; font-family: Arial;\">What does the Crude Birth Rate (CBR) measure?<br />\nA) Number of births per 1000 women aged 15-49 years<br />\nB) Number of births per 1000 population<br />\nC) Number of births per 1000 live births<br />\nD) Number of births per 1000 households</p>', 'B', 'blank.jpg', NULL, NULL),
(198, '2024/2025', 'Professional Diploma in Health Information Management', '300', 'First', 'BIOSTATISTICS', 'PREPARATORY', 'OBJECTIVE', 'GENERAL', 100, 100, 'text', 97, '<p style=\"font-size: 24px; font-family: Arial;\">Which demographic measure refers to the average number of years a person is expected to live?<br />\nA) Life Expectancy<br />\nB) Median Age<br />\nC) Mortality Rate<br />\nD) Crude Death Rate</p>', 'A', 'blank.jpg', NULL, NULL),
(199, '2024/2025', 'Professional Diploma in Health Information Management', '300', 'First', 'BIOSTATISTICS', 'PREPARATORY', 'OBJECTIVE', 'GENERAL', 100, 100, 'text', 98, '<p style=\"font-size: 24px; font-family: Arial;\">What does the term \"Neonatal Mortality Rate\" (NMR) refer to?<br />\nA) Deaths of infants under 28 days per 1000 live births<br />\nB) Deaths of infants under 1 year per 1000 live births C) Deaths of children under 5 years per 1000 live births<br />\nD) Deaths of infants under 7 days per 1000 live births</p>', 'A', 'blank.jpg', NULL, NULL),
